export default function AttractionsListSkeleton() {
  return (
    <div className="tw-grid tw-grid-cols-1 sm:tw-grid-cols-2 lg:tw-grid-cols-3 tw-gap-5 tw-mt-4">
      {[...Array(6)].map((x, i) => (
        <div
          className="tw-rounded-2xl tw-border tw-border-solid tw-border-[#ece9f1] tw-bg-white tw-overflow-hidden tw-animate-pulse"
          key={i}
        >
          <div className="tw-aspect-[4/3] tw-w-full tw-bg-[#e6e3ec]" />
          <div className="tw-p-4">
            <div className="tw-h-[1rem] tw-w-3/4 tw-bg-[#e6e3ec] tw-rounded tw-mb-2" />
            <div className="tw-h-[0.8rem] tw-w-full tw-bg-[#e6e3ec] tw-rounded tw-mb-1.5" />
            <div className="tw-h-[0.8rem] tw-w-2/3 tw-bg-[#e6e3ec] tw-rounded" />
          </div>
        </div>
      ))}
    </div>
  );
}
